            <div class="preview-image-container compact" @mousemove="onHoverOriginal" @mouseleave="hideHover">
              <img v-if="originalPreview && !isRendering" :src="originalPreview" :alt="`${gridSize.width}×${gridSize.height} 原始色像素画预览`" class="preview-image" @load="onImageLoad" />
              <div v-else-if="isRendering" class="loading-preview">
