          <button class="btn-secondary tools-toggle" @click="toolsOpen = !toolsOpen">
            {{ toolsOpen ? t('preview.collapseConfig') : t('preview.expandConfig') }}
          </button>
          <transition name="fade">
            <div v-show="toolsOpen" class="tools-grid">
