              </div>
              <div class="tool-item">
                <label for="gamma">Gamma</label>
                <div class="row">
                  <input id="gamma" type="range" min="0.5" max="2.5" step="0.05" v-model.number="gamma" @input="refreshDebounced" />
                  <span>{{ gamma.toFixed(2) }}</span>
                </div>
              </div>
              <div class="tool-item">
                <label for="brightness">亮度</label>
                <div class="row">
                  <input id="brightness" type="range" min="-1" max="1" step="0.05" v-model.number="brightness" @input="refreshDebounced" />
                  <span>{{ brightness.toFixed(2) }}</span>
                </div>
              </div>
              <div class="tool-item">
                <label>色彩约束</label>
                <div class="row">
                  <span>高光</span>
                  <input type="range" min="0" max="1" step="0.05" v-model.number="clampHighlights" @input="refreshDebounced" />
