// 基于 previewStore 的 base64 读取像素（不依赖 DOM）
async function getCurrentPreviewPixels() {
  const base64 = customPreview.value || originalPreview.value
  if (!base64) return extractedColors.value?.pixels || []

  const { width, height } = gridSize.value
  const img = new Image()
  // dataURL 同源，无需跨域设置
  const pixels: Array<Array<{ r: number; g: number; b: number; hex: string }>> = []

  await new Promise<void>((resolve) => {
    img.onload = () => resolve()
    img.src = base64
  })

  const canvas = document.createElement('canvas')
  const ctx = canvas.getContext('2d')!
  canvas.width = width
  canvas.height = height
  // 将预览图按网格尺寸绘制，得到网格级像素
  ctx.drawImage(img, 0, 0, width, height)

  for (let y = 0; y < height; y++) {
    pixels[y] = []
    for (let x = 0; x < width; x++) {
      const d = ctx.getImageData(x, y, 1, 1).data
      const r = d[0], g = d[1], b = d[2]
      const hex = `#${r.toString(16).padStart(2,'0')}${g.toString(16).padStart(2,'0')}${b.toString(16).padStart(2,'0')}`
      pixels[y][x] = { r, g, b, hex }
    }
  }

  return pixels
}

async function downloadExcelPixelArt() {
  if (!extractedColors.value) {
    alert(t('preview.uploadImageFirst'))
    return
  }
  try {
    // 导出进度 UI
    const progressBar = document.createElement('div')
    progressBar.style.position = 'fixed'
    progressBar.style.left = '50%'
    progressBar.style.top = '20px'
    progressBar.style.transform = 'translateX(-50%)'
    progressBar.style.width = '360px'
    progressBar.style.padding = '8px'
    progressBar.style.background = 'rgba(0,0,0,0.7)'
    progressBar.style.color = '#fff'
    progressBar.style.borderRadius = '8px'
    progressBar.style.boxShadow = '0 6px 20px rgba(0,0,0,0.2)'
    progressBar.style.zIndex = '2000'
    const bar = document.createElement('div')
    bar.style.height = '6px'
    bar.style.background = '#28a745'
    bar.style.width = '0%'
    bar.style.borderRadius = '4px'
    bar.style.transition = 'width .15s ease'
    const text = document.createElement('div')
    text.style.fontSize = '12px'
    text.style.marginTop = '6px'
    text.innerText = t('preview.preparing')
    const track = document.createElement('div')
    track.style.height = '6px'
    track.style.background = 'rgba(255,255,255,0.25)'
    track.style.borderRadius = '4px'
    track.appendChild(bar)
    progressBar.appendChild(track)
    progressBar.appendChild(text)
    document.body.appendChild(progressBar)

    const onProgress = (p: number, msg?: string) => {
      const pct = Math.max(0, Math.min(1, p))
      bar.style.width = (pct * 100).toFixed(0) + '%'
      if (msg) text.innerText = `${msg} ${(pct * 100).toFixed(0)}%`
    }

    // 直接基于 previewStore 的 base64 读取像素（包含画风与归并后的最终效果）
    const currentPreviewData = await getCurrentPreviewPixels()
    
    const excelBlob = await generateExcelPixelArt(
      currentPreviewData,
      hasCustomColors.value ? customColors.value.map(c => ({ r: c.r, g: c.g, b: c.b, hex: c.hex, name: c.name || `颜色${c.id}`, id: c.id })) : [],
      selectedAlgorithm.value,
      { onProgress, baseFabricColor: colorStore.baseFabricColor || undefined }
    )

    const url = URL.createObjectURL(excelBlob)
    const link = document.createElement('a')
    link.href = url
    link.download = `pixel-art-excel-${gridSize.value.width}x${gridSize.value.height}.xlsx`
    link.click()
    URL.revokeObjectURL(url)
    document.body.removeChild(progressBar)
  } catch (e) {
    console.error(t('preview.excelGenerationFailed'), e)
    alert(t('preview.excelGenerationFailedRetry'))
  }
}

