function computeGridXY(evt: MouseEvent): { gx: number; gy: number; ok: boolean; pageX: number; pageY: number } {
  if (!extractedColors.value) return { gx: 0, gy: 0, ok: false, pageX: evt.pageX, pageY: evt.pageY }
  const target = (evt.currentTarget as HTMLElement | null)
  if (!target) return { gx: 0, gy: 0, ok: false, pageX: evt.pageX, pageY: evt.pageY }
  const rect = target.getBoundingClientRect()
  const relX = evt.clientX - rect.left
  const relY = evt.clientY - rect.top
  const w = rect.width
  const h = rect.height
  // 图片按 pixelSize*scale 渲染，容器尺寸即为预览尺寸
  const gridW = extractedColors.value.width
  const gridH = extractedColors.value.height
  if (w <= 0 || h <= 0) return { gx: 0, gy: 0, ok: false, pageX: evt.pageX, pageY: evt.pageY }
  const gx = Math.floor(relX / w * gridW)
  const gy = Math.floor(relY / h * gridH)
  if (gx < 0 || gy < 0 || gx >= gridW || gy >= gridH) return { gx, gy, ok: false, pageX: evt.clientX, pageY: evt.clientY }
  return { gx, gy, ok: true, pageX: evt.clientX, pageY: evt.clientY }
}

let lastHoverTimeOriginal = 0
let lastGXOriginal = -1
let lastGYOriginal = -1
function onHoverOriginal(evt: MouseEvent) {
  if (!extractedColors.value) return
  const now = performance.now()
  const pos = computeGridXY(evt)
  if (!pos.ok) { hideHover(); return }
  const fastMove = (now - lastHoverTimeOriginal) < 16
  // 位置及时更新
  hover.value.x = pos.pageX
  hover.value.y = pos.pageY
  // 内容仅在网格坐标变化或超出节流间隔时更新
  if (fastMove && pos.gx === lastGXOriginal && pos.gy === lastGYOriginal) {
    hover.value.visible = true
    return
  }
  const grid = colorStore.extractedColors?.pixels
  if (!grid) { hideHover(); return }
  const c = grid[pos.gy]?.[pos.gx]
  if (!c) { hideHover(); return }
  hover.value.visible = true
  hover.value.hex = c.hex
  hover.value.title = t('preview.originalColor')
  hover.value.extra = `RGB(${c.r}, ${c.g}, ${c.b})`
  lastGXOriginal = pos.gx
  lastGYOriginal = pos.gy
  lastHoverTimeOriginal = now
}

