<template>
  <div class="card">
    <h3 class="card-title">{{ $t('customColors.title') }}</h3>

    <!-- 左侧悬浮 删除历史（桌面端） -->
    <div v-if="deletedColors.length" class="deleted-floating" :aria-label="$t('customColors.deleteHistory')">
      <div class="deleted-floating-header">
        <strong>{{ $t('customColors.deleteHistory') }}</strong>
        <span class="count">{{ deletedColors.length }}</span>
        <button class="btn-link" @click="clearHistory" :title="$t('customColors.clearHistory')">{{
          $t('customColors.clearHistory') }}</button>
      </div>
      <div class="deleted-floating-list">
        <div v-for="c in deletedColors" :key="'del-float-' + c.id" class="deleted-floating-item"
          :title="c.name || ($t('customColors.colorPrefix') + c.id)">
          <div class="color-swatch" :style="{ backgroundColor: c.hex }"></div>
          <div class="meta">
            <div class="name">{{ c.name || ($t('customColors.colorPrefix') + c.id) }}</div>
            <div class="hex">{{ c.hex.toUpperCase() }}</div>
          </div>
          <button class="btn-secondary small" @click="restoreColor(c.id)">{{ $t('customColors.restore') }}</button>
        </div>
      </div>
    </div>

    <!-- 画风切换功能 -->
    <div class="art-style-section">
      <h4 class="section-title">{{ $t('customColors.artStyle.title') }}</h4>
      <div class="style-selector">
        <label for="artStyle">{{ $t('customColors.artStyle.select') }}</label>
        <select id="artStyle" v-model="selectedArtStyle" @change="onArtStyleChange" class="style-select">
          <option value="">{{ $t('customColors.artStyle.none') }}</option>
          <option v-for="style in artStyles" :key="style.id" :value="style.id">
            {{ style.name }} - {{ style.description }}
          </option>
          <option value="brand-dmc">{{ $t('customColors.artStyle.dmcBrand') }}</option>
        </select>
        <button v-if="selectedArtStyle !== currentArtStyle" @click="applyArtStyle" class="apply-style-btn">
          {{ $t('customColors.artStyle.apply') }}
        </button>
      </div>
      <div v-if="selectedArtStyle !== undefined" class="style-info">
        <p v-if="selectedArtStyle" class="style-description">
          <strong>{{ $t('customColors.artStyle.recommendedAlgorithm') }}</strong>
          <span class="algorithm-tag">{{ getAlgorithmDisplayName(getSelectedStyleAlgorithm()) }}</span>
        </p>
        <p v-if="selectedArtStyle" class="style-description">
          <strong>{{ $t('customColors.artStyle.colorCount') }}</strong> {{ getSelectedStyleColors().length }} {{
            $t('common.colors') }}
        </p>
        <p v-if="!selectedArtStyle" class="style-description">
          <strong>{{ $t('customColors.artStyle.status') }}</strong> <span class="algorithm-tag">{{
            $t('customColors.artStyle.noCustomColors') }}</span>
        </p>
        <p v-if="brandDisclaimer && selectedArtStyle === 'brand-dmc'" class="style-description" style="opacity:.9;">
          {{ brandDisclaimer }}
        </p>
      </div>
    </div>

    <!-- 颜色归并阈值设置 -->
    <div class="color-merge-section">
      <h4 class="color-merge-title">{{ $t('customColors.colorMerge.title') }}</h4>
      <div class="merge-controls">
        <div class="merge-mode">
          <label for="mergeMode">{{ $t('customColors.colorMerge.mode') }}</label>
          <select id="mergeMode" v-model="mergeMode" class="merge-select">
            <option value="rgb">{{ $t('customColors.colorMerge.rgbThreshold') }}</option>
            <option value="cielab">{{ $t('customColors.colorMerge.cielabThreshold') }}</option>
          </select>
        </div>

        <div class="merge-threshold">
          <label for="mergeThreshold">
            {{ mergeMode === 'rgb' ? $t('customColors.colorMerge.rgbThreshold') :
              $t('customColors.colorMerge.cielabThreshold') }}:
            <span class="threshold-value">{{ mergeThreshold }}</span>
          </label>
          <input id="mergeThreshold" type="range" v-model.number="mergeThreshold" :min="mergeMode === 'rgb' ? 0 : 0.1"
            :max="mergeMode === 'rgb' ? 50 : 10" :step="mergeMode === 'rgb' ? 1 : 0.1" class="threshold-slider"
            @input="onThresholdChange" />
          <div class="threshold-info">
            <span v-if="mergeMode === 'rgb'">
              {{ $t('customColors.colorMerge.rgbRecommend') }}
            </span>
            <span v-else>
              {{ $t('customColors.colorMerge.cielabRecommend') }}
            </span>
          </div>
        </div>

        <div class="merge-base-color">
          <label for="baseHex">{{ $t('customColors.colorMerge.baseColor') }}(#RRGGBB):</label>
          <div class="hex-input-wrapper">
            <span class="hex-prefix">#</span>
            <input id="baseHex" type="text" v-model="baseHexNoHash" maxlength="6" placeholder="FFFFFF"
              class="hex-input" />
          </div>
          <small class="hint-text">{{ $t('customColors.colorMerge.baseColor') }}</small>
        </div>

        <div class="merge-actions">
          <button @click="applyColorMerge" class="merge-btn" :disabled="isMerging">
            {{ isMerging ? $t('customColors.colorMerge.merging') : $t('customColors.colorMerge.applyMerge') }}
          </button>
          <button @click="resetMergeSettings" class="reset-btn">{{ $t('customColors.colorMerge.resetSettings')
            }}</button>
        </div>

        <div v-if="mergeResult" class="merge-result">
          <p class="result-info">
            <strong>{{ $t('customColors.colorMerge.mergeResult') }}</strong>
            {{ $t('customColors.colorMerge.fromColors') }} {{ mergeResult.originalCount }} {{ $t('common.colors') }} {{
              $t('customColors.colorMerge.toColors') }} {{ mergeResult.mergedCount }} {{ $t('common.colors') }}
            <span class="reduction">({{ $t('customColors.colorMerge.reduction') }} {{ mergeResult.reduction }}%)</span>
          </p>
        </div>
      </div>
    </div>

    <div class="color-form">
      <!-- 输入方式切换 -->
      <div class="input-mode-switch">
        <label class="switch-label">
          <input type="radio" v-model="inputMode" value="rgb" name="inputMode" />
          <span class="switch-text">{{ $t('customColors.colorMerge.rgbInput') }}</span>
        </label>
        <label class="switch-label">
          <input type="radio" v-model="inputMode" value="hex" name="inputMode" />
          <span class="switch-text">{{ $t('customColors.colorMerge.hexInput') }}</span>
        </label>
      </div>

      <!-- RGB输入模式 -->
      <div v-if="inputMode === 'rgb'" class="color-inputs">
        <div class="color-input-group">
          <label for="colorR">R:</label>
          <input id="colorR" type="number" v-model.number="newColor.r" min="0" max="255" placeholder="0-255"
            @input="updateFromRGB" />
        </div>

        <div class="color-input-group">
          <label for="colorG">G:</label>
          <input id="colorG" type="number" v-model.number="newColor.g" min="0" max="255" placeholder="0-255"
            @input="updateFromRGB" />
        </div>

        <div class="color-input-group">
          <label for="colorB">B:</label>
          <input id="colorB" type="number" v-model.number="newColor.b" min="0" max="255" placeholder="0-255"
            @input="updateFromRGB" />
        </div>
      </div>

      <!-- 16进制输入模式 -->
      <div v-else class="color-inputs">
        <div class="hex-input-group">
          <label for="colorHex">{{ $t('customColors.colorMerge.hexLabel') }}</label>
          <div class="hex-input-wrapper">
            <span class="hex-prefix">#</span>
            <input id="colorHex" type="text" v-model="hexInput" placeholder="000000" maxlength="6"
              pattern="[0-9A-Fa-f]{6}" @input="updateFromHexWithHash" class="hex-input"
              :class="{ 'input-valid': isValidHexInput }" />
          </div>
          <div v-if="hexInput" class="hex-input-hint">
            <span v-if="hexInput.replace('#', '').length < 6" class="hint-text">
              {{ $t('customColors.colorMerge.hexInputHint') }} {{ hexInput.replace('#', '').length }}{{
                $t('customColors.colorMerge.hexInputHint2') }}
            </span>
            <span v-else class="hint-text success">
              {{ $t('customColors.colorMerge.hexComplete') }}
            </span>
          </div>
        </div>
      </div>

      <div class="color-preview">
        <div class="color-swatch" :style="{ backgroundColor: `rgb(${newColor.r}, ${newColor.g}, ${newColor.b})` }">
        </div>
        <div class="color-values-display">
          <span class="hex-value">{{ newColorHex }}</span>
          <span class="rgb-value">RGB({{ newColor.r }}, {{ newColor.g }}, {{ newColor.b }})</span>
        </div>
        <input type="color" v-model="newColorPickerHex" :aria-label="$t('customColors.colorMerge.selectColor')" />
      </div>

      <div class="color-form-actions">
        <input v-model="newColor.name" type="text" :placeholder="$t('customColors.colorMerge.colorNamePlaceholder')"
          class="color-name-input" />
        <button class="btn-success" @click="addColor" :disabled="!isValidColorValue">
          {{ $t('customColors.colorMerge.addColor') }}
        </button>
      </div>
    </div>


    <div v-if="customColors.length > 0" class="color-list">
      <h4>{{ $t('customColors.colorMerge.addedColors') }} ({{ customColors.length }})</h4>
      <div class="color-items">
        <div v-for="color in customColors" :key="color.id" class="color-item">
          <div class="color-swatch" :style="{ backgroundColor: color.hex }"></div>
          <div class="color-info">
            <div class="color-values">
              <span class="rgb-values">RGB({{ color.r }}, {{ color.g }}, {{ color.b }})</span>
              <span class="hex-value">{{ color.hex }}</span>
            </div>
            <div class="color-name">{{ color.name }}</div>
          </div>
          <button class="btn-secondary edit-btn" @click="openEditColor(color)"
            :title="$t('customColors.colorMerge.editColor')">
            ✎
          </button>
          <button class="btn-danger remove-btn" @click="removeColor(color.id)"
            :title="$t('customColors.colorMerge.deleteColor')">
            ×
          </button>
        </div>
      </div>
    </div>

    <div v-else class="no-colors">
      <p>{{ $t('customColors.colorMerge.noCustomColorsYet') }}</p>
      <p class="text-muted">{{ $t('customColors.colorMerge.addColorsHint') }}</p>
    </div>
    <!-- 导出导入功能 -->
    <div class="export-import-section">
      <h4>{{ $t('customColors.colorMerge.exportImport') }}</h4>

      <!-- 导出功能 -->
      <div class="export-section">
        <h5>{{ $t('customColors.colorMerge.exportColors') }}</h5>
        <p class="section-desc">{{ $t('customColors.colorMerge.exportDesc') }}</p>
        <div class="export-actions">
          <button class="btn-primary" @click="exportColors" :disabled="customColors.length === 0">
            {{ $t('customColors.colorMerge.exportColors') }}
          </button>
          <div v-if="exportedString" class="export-result">
            <label for="exportString">{{ $t('customColors.colorMerge.exportString') }}</label>
            <div class="export-string-wrapper">
              <input id="exportString" type="text" :value="exportedString" readonly class="export-string-input" />
              <button class="btn-secondary copy-btn" @click="copyToClipboard"
                :title="$t('customColors.colorMerge.copyToClipboard')">
                📋
              </button>
            </div>
          </div>
        </div>
      </div>

      <!-- 导入功能 -->
      <div class="import-section">
        <h5>{{ $t('customColors.colorMerge.importColors') }}</h5>
        <p class="section-desc">{{ $t('customColors.colorMerge.importDesc') }}</p>
        <div class="import-actions">
          <div class="import-input-wrapper">
            <input v-model="importString" type="text" :placeholder="$t('customColors.colorMerge.pasteString')"
              class="import-string-input" />
            <button class="btn-success" @click="importColors" :disabled="!importString.trim()">
              {{ $t('customColors.colorMerge.importColor') }}
            </button>
          </div>
          <div v-if="importResult" class="import-result" :class="importResult.type">
            {{ importResult.message }}
          </div>
        </div>
      </div>

      <!-- 自动生成调色板 -->
      <div class="export-import-section">
        <h4>{{ $t('customColors.colorMerge.generatePalette') }}</h4>
        <p class="section-desc">{{ $t('customColors.colorMerge.generatePaletteDesc') }}</p>
        <div class="export-actions">
          <div class="import-input-wrapper">
            <label style="min-width: 110px;">{{ $t('customColors.colorMerge.targetColorCount') }}</label>
            <input type="range" v-model.number="targetPaletteSize" min="4" max="128" step="1" style="width:110px;" />
            <span style="min-width: 40px; text-align:center;">{{ targetPaletteSize }}</span>
            <button class="btn-primary" @click="generateAutoPalette"
              :disabled="!canGeneratePalette || isGeneratingPalette">
              {{ isGeneratingPalette ? $t('customColors.colorMerge.generating') :
                $t('customColors.colorMerge.generatePaletteBtn') }}
            </button>
          </div>
          <div v-if="paletteResultMsg" class="import-result" :class="paletteResultType">{{ paletteResultMsg }}</div>
        </div>
      </div>

      <!-- 批量导入功能 -->
      <div class="batch-import-section">
        <h5>{{ $t('customColors.colorMerge.batchImport') }}</h5>
        <p class="section-desc">{{ $t('customColors.colorMerge.batchImportDesc') }}
        </p>
        <div class="batch-import-actions">
          <div class="batch-import-input-wrapper">
            <textarea v-model="batchImportString" :placeholder="$t('customColors.colorMerge.batchImportPlaceholder')"
              class="batch-import-textarea" rows="5"></textarea>
            <button class="btn-warning" @click="batchImportColors" :disabled="!batchImportString.trim()">
              {{ $t('customColors.colorMerge.batchImportBtn') }}
            </button>
          </div>
          <div v-if="batchImportResult" class="import-result" :class="batchImportResult.type">
            {{ batchImportResult.message }}
          </div>
        </div>
      </div>
    </div>
    <!-- 编辑颜色弹窗 -->
    <div v-if="isEditOpen" class="modal-overlay" @click.self="closeEdit">
      <div class="modal">
        <h4 class="modal-title">{{ $t('customColors.editColorModal') }}</h4>
        <div class="modal-body">
          <div class="edit-preview">
            <div class="color-swatch" :style="{ backgroundColor: editHex }"></div>
            <div class="color-values-display">
              <span class="hex-value">{{ editHex }}</span>
              <span class="rgb-value">RGB({{ editColor.r }}, {{ editColor.g }}, {{ editColor.b }})</span>
            </div>
            <input type="color" v-model="editHexColorPicker" :aria-label="$t('customColors.colorMerge.selectColor')" />
          </div>
          <div class="color-inputs">
            <div class="color-input-group">
              <label>R:</label>
              <input type="number" v-model.number="editColor.r" min="0" max="255" @input="syncEditHexFromRgb" />
            </div>
            <div class="color-input-group">
              <label>G:</label>
              <input type="number" v-model.number="editColor.g" min="0" max="255" @input="syncEditHexFromRgb" />
            </div>
            <div class="color-input-group">
              <label>B:</label>
              <input type="number" v-model.number="editColor.b" min="0" max="255" @input="syncEditHexFromRgb" />
            </div>
            <div class="color-input-group">
              <label>HEX:</label>
              <div class="hex-input-wrapper">
                <span class="hex-prefix">#</span>
                <input type="text" v-model="editHexNoHash" maxlength="6" @input="syncEditRgbFromHex"
                  class="hex-input" />
              </div>
            </div>
          </div>
          <div class="color-input-group" style="margin-top: .5rem;">
            <label>{{ $t('customColors.colorMerge.nameLabel') }}</label>
            <input type="text" v-model="editName" :placeholder="$t('customColors.colorMerge.colorNamePlaceholder2')" />
          </div>
        </div>
        <div class="modal-actions">
          <button class="btn-secondary" @click="closeEdit">{{ $t('customColors.colorMerge.cancel') }}</button>
          <button class="btn-success" @click="saveEdit" :disabled="!isEditValid">{{ $t('customColors.colorMerge.save')
            }}</button>
        </div>
      </div>
    </div>

  </div>
</template>

<script setup lang="ts">
import { ref, computed, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { useColorStore, type ColorPoint } from '../stores/colorStore'
import { rgbToHex, hexToRgb, isValidColor, generatePaletteFromExtractedColors } from '../utils/colorUtils'
import { usePreviewStore } from '../stores/previewStore'

const { t } = useI18n()

const colorStore = useColorStore()

// 画风相关状态
const selectedArtStyle = ref('')
const artStyles = computed(() => colorStore.getArtStyles())
const brandDisclaimer = computed(() => colorStore.brandDisclaimer)
const currentArtStyle = computed(() => colorStore.getCurrentArtStyle())

const inputMode = ref<'rgb' | 'hex'>('rgb')
const hexInput = ref('')

const newColor = ref({
  r: 0,
  g: 0,
  b: 0,
  name: ''
})

// 导出导入相关状态
const exportedString = ref('')
const importString = ref('')

// 颜色归并相关状态
const mergeMode = computed({
  get: () => colorStore.mergeMode,
  set: (val: 'rgb' | 'cielab') => colorStore.setMergeMode(val)
})
const mergeThreshold = computed({
  get: () => colorStore.mergeThreshold,
  set: (val: number) => colorStore.setMergeThreshold(val)
})
const isMerging = ref(false)
const mergeResult = ref<{
  originalCount: number
  mergedCount: number
  reduction: number
} | null>(null)
const importResult = ref<{ type: 'success' | 'error'; message: string } | null>(null)

// 批量导入相关状态
const batchImportString = ref('')
const batchImportResult = ref<{ type: 'success' | 'error'; message: string } | null>(null)

const customColors = computed(() => colorStore.customColors)
const deletedColors = computed(() => colorStore.getDeletedColors())

// 自动调色板状态
const targetPaletteSize = ref(32)
const isGeneratingPalette = ref(false)
const paletteResultMsg = ref('')
const paletteResultType = ref<'success' | 'error'>('success')
const canGeneratePalette = computed(() => !!colorStore.extractedColors)

// 底色输入（仅在应用时写入store，不做实时监听）
const baseHexNoHash = ref(colorStore.baseFabricColor?.hex.replace('#', ''))

async function generateAutoPalette() {
  if (!colorStore.extractedColors) {
    paletteResultType.value = 'error'
    paletteResultMsg.value = t('customColors.colorMerge.pleaseUploadFirst')
    return
  }
  isGeneratingPalette.value = true
  paletteResultMsg.value = ''
  try {
    const palette = await generatePaletteFromExtractedColors(
      colorStore.extractedColors.pixels,
      Math.max(4, Math.min(128, targetPaletteSize.value)),
      { sampleRate: 0.3 }
    )
    // 替换自定义颜色
    colorStore.clearCustomColors()
    for (const c of palette) {
      colorStore.addCustomColor({ r: c.r, g: c.g, b: c.b, hex: c.hex, name: c.name })
    }
    // 切换到 CIEDE2000 匹配
    colorStore.setColorMatchingAlgorithm('ciede2000')
    paletteResultType.value = 'success'
    paletteResultMsg.value = `${t('customColors.colorMerge.generatedColors')} ${palette.length} ${t('customColors.colorMerge.representativeColors')}`
  } catch (e) {
    console.error(e)
    paletteResultType.value = 'error'
    paletteResultMsg.value = t('customColors.colorMerge.generateFailed')
  } finally {
    isGeneratingPalette.value = false
  }
}

// 编辑颜色弹窗状态
const isEditOpen = ref(false)
const editingId = ref<number | null>(null)
const editColor = ref({ r: 0, g: 0, b: 0 })
const editHex = computed(() => rgbToHex(editColor.value.r, editColor.value.g, editColor.value.b))
const editHexColorPicker = computed({
  get: () => editHex.value,
  set: (val: string) => {
    const rgb = hexToRgb(val)
    if (rgb) {
      editColor.value = { r: rgb.r, g: rgb.g, b: rgb.b }
    }
  }
})
const editHexNoHash = computed({
  get: () => editHex.value.replace('#', ''),
  set: (v: string) => {
    const clean = v.replace('#', '')
    if (/^[0-9A-Fa-f]{0,6}$/.test(clean)) {
      const padded = clean.padEnd(6, '0')
      const rgb = hexToRgb('#' + padded)
      if (rgb) {
        editColor.value = { r: rgb.r, g: rgb.g, b: rgb.b }
      }
    }
  }
})
const editName = ref('')
const isEditValid = computed(() => isValidColor(editColor.value.r, editColor.value.g, editColor.value.b))

function openEditColor(color: { id: number; r: number; g: number; b: number; hex: string; name?: string }) {
  editingId.value = color.id
  editColor.value = { r: color.r, g: color.g, b: color.b }
  editName.value = color.name || ''
  isEditOpen.value = true
}

function closeEdit() {
  isEditOpen.value = false
  editingId.value = null
}

function syncEditHexFromRgb() {
  // computed editHex will reflect automatically
}

function syncEditRgbFromHex() {
  // handled in editHexNoHash setter
}

function saveEdit() {
  if (!isEditValid.value || editingId.value == null) return
  const hex = editHex.value
  colorStore.updateCustomColor(editingId.value, {
    r: editColor.value.r,
    g: editColor.value.g,
    b: editColor.value.b,
    hex,
    name: editName.value.trim() || undefined
  })
  closeEdit()
}

const newColorHex = computed(() => {
  return rgbToHex(newColor.value.r, newColor.value.g, newColor.value.b)
})

const newColorPickerHex = computed({
  get: () => newColorHex.value,
  set: (val: string) => {
    const rgb = hexToRgb(val)
    if (rgb) {
      newColor.value.r = rgb.r
      newColor.value.g = rgb.g
      newColor.value.b = rgb.b
      hexInput.value = val.replace('#', '')
    }
  }
})

const isValidColorValue = computed(() => {
  return isValidColor(newColor.value.r, newColor.value.g, newColor.value.b)
})

const isValidHexInput = computed(() => {
  const hex = hexInput.value.trim()
  // 移除可能存在的#前缀，只保留16进制字符
  const cleanHex = hex.replace('#', '')
  return cleanHex.length > 0 && /^[0-9A-Fa-f]*$/.test(cleanHex)
})

// 从RGB值更新16进制输入
function updateFromRGB() {
  hexInput.value = newColorHex.value.replace('#', '')
}

// 从16进制输入更新RGB值
function updateFromHex() {
  const hex = hexInput.value.trim()

  // 移除可能存在的#前缀，只保留16进制字符
  const cleanHex = hex.replace('#', '')

  // 如果输入长度不足6位，用0补齐
  if (cleanHex.length > 0 && cleanHex.length <= 6 && /^[0-9A-Fa-f]*$/.test(cleanHex)) {
    const paddedHex = cleanHex.padEnd(6, '0')
    const rgb = hexToRgb(paddedHex)
    if (rgb) {
      newColor.value.r = rgb.r
      newColor.value.g = rgb.g
      newColor.value.b = rgb.b
    }
  }
}

// 从16进制输入更新RGB值（带#前缀）
function updateFromHexWithHash() {
  const hex = hexInput.value.trim()

  // 移除可能存在的#前缀，只保留16进制字符
  const cleanHex = hex.replace('#', '')

  // 如果输入长度不足6位，用0补齐
  if (cleanHex.length > 0 && cleanHex.length <= 6 && /^[0-9A-Fa-f]*$/.test(cleanHex)) {
    const paddedHex = cleanHex.padEnd(6, '0')
    const rgb = hexToRgb('#' + paddedHex)
    if (rgb) {
      newColor.value.r = rgb.r
      newColor.value.g = rgb.g
      newColor.value.b = rgb.b
    }
  }
}

