async function applyColorMerge() {
  if (!colorStore.extractedColors || colorStore.extractedColors.pixels.length === 0) {
    alert('请先上传图片并提取颜色')
    return
  }

  isMerging.value = true
  mergeResult.value = null

  try {
    // 应用底色设置（仅在点击时）
    const clean = baseHexNoHash.value?.trim() || ''
    if (clean && /^[0-9A-Fa-f]{6}$/.test(clean)) {
      const hex = '#' + clean.toUpperCase()
      const rgb = hexToRgb(hex)
      if (rgb) {
        colorStore.setBaseFabricColor({ ...rgb, hex })
      }
    } else {
      colorStore.setBaseFabricColor(null)
    }
    // 直接触发相近色预览图更新，颜色归并会在 generatePreviewImage 中自动执行
    const previewStore = usePreviewStore()
    await previewStore.renderCustomPreviewOnly()

    // 从 previewStore 获取归并结果
    mergeResult.value = previewStore.mergeResult

  } catch (error) {
    console.error('颜色归并失败:', error)
    alert('颜色归并失败，请重试')
  } finally {
    isMerging.value = false
  }
}

// 导出颜色配置为密文字符串
function exportColors() {
  try {
    const colorData = customColors.value.map(color => ({
      r: color.r,
      g: color.g,
      b: color.b,
      name: color.name
    }))

    // 将颜色数据转换为JSON字符串，然后进行Base64编码
    const jsonString = JSON.stringify(colorData)

    // 使用 encodeURIComponent 处理中文字符，然后进行 Base64 编码
    const encodedString = btoa(encodeURIComponent(jsonString))

    exportedString.value = encodedString
    importResult.value = null // 清除之前的导入结果
  } catch (error) {
    console.error('导出颜色配置失败:', error)
    importResult.value = {
      type: 'error',
      message: '导出失败，请重试'
    }
  }
}

// 导入颜色配置
function importColors() {
  try {
    if (!importString.value.trim()) {
      importResult.value = {
        type: 'error',
        message: '请输入要导入的密文字符串'
      }
      return
    }

    // 解码Base64字符串，然后解码URI组件
    const decodedString = decodeURIComponent(atob(importString.value.trim()))
    const colorData = JSON.parse(decodedString)

    // 验证数据格式
    if (!Array.isArray(colorData)) {
      throw new Error('无效的颜色数据格式')
    }

    // 验证每个颜色对象
    for (const color of colorData) {
      if (typeof color.r !== 'number' || typeof color.g !== 'number' || typeof color.b !== 'number' || typeof color.name !== 'string') {
        throw new Error('颜色数据格式不正确')
      }

      // 验证RGB值范围
      if (color.r < 0 || color.r > 255 || color.g < 0 || color.g > 255 || color.b < 0 || color.b > 255) {
        throw new Error('RGB值超出有效范围(0-255)')
      }
    }

    // 清空现有颜色并导入新颜色
    colorStore.clearCustomColors()

    for (const color of colorData) {
      colorStore.addCustomColor({
        r: color.r,
        g: color.g,
        b: color.b,
        hex: rgbToHex(color.r, color.g, color.b),
        name: color.name
      })
    }

    // 显示成功消息
    importResult.value = {
      type: 'success',
      message: `成功导入 ${colorData.length} 个颜色`
    }

    // 清空导入输入框
    importString.value = ''

    // 清空导出结果
    exportedString.value = ''

  } catch (error) {
    console.error('导入颜色配置失败:', error)
    importResult.value = {
      type: 'error',
      message: '导入失败：无效的密文字符串或数据格式错误'
    }
  }
}

// 批量导入颜色
function batchImportColors() {
  try {
    if (!batchImportString.value.trim()) {
      batchImportResult.value = {
        type: 'error',
        message: '请输入要批量导入的颜色值'
      }
      return
    }

    const inputText = batchImportString.value.trim()
    let colorData: Array<{ name: string; r: number; g: number; b: number }> = []

    console.log('输入文本：', inputText)
    console.log('是否包含分号：', inputText.includes(';'))
    console.log('分号位置：', inputText.indexOf(';'))

    // 检测输入格式：如果包含分号，按分号分割；否则按逗号分割
    if (inputText.includes(';')) {
      // 格式：用分号分隔的不同颜色行
      const colorLines = inputText.split(';').filter(line => line.trim())

      if (colorLines.length === 0) {
        throw new Error('没有找到有效的颜色数据')
      }

      console.log('检测到分号分隔格式，行数：', colorLines.length)

      for (let i = 0; i < colorLines.length; i++) {
        const line = colorLines[i].trim()
        if (!line) continue

        const parts = line.split(',').map(part => part.trim())
        console.log(`第${i + 1}行：${line}，分割后：`, parts)

        // 智能识别输入格式
        if (parts.length === 1) {
          // 格式：单个16进制颜色值
          const hexValue = parts[0]
          if (hexValue.startsWith('#')) {
            const rgb = hexToRgb(hexValue)
            if (rgb) {
              colorData.push({
                name: `颜色${i + 1}`,
                r: rgb.r,
                g: rgb.g,
                b: rgb.b
              })
            } else {
              throw new Error(`第${i + 1}行无效的16进制颜色值：${hexValue}`)
            }
          } else {
            throw new Error(`第${i + 1}行格式错误：${line}，应为：#RRGGBB 或 颜色名称,R,G,B`)
          }
        } else if (parts.length === 2) {
          // 格式：颜色名称,#RRGGBB
          const [name, hexValue] = parts

          if (!name) {
            throw new Error(`第${i + 1}行颜色名称不能为空：${line}`)
          }

          if (hexValue.startsWith('#')) {
            const rgb = hexToRgb(hexValue)
            if (rgb) {
              colorData.push({ name, r: rgb.r, g: rgb.g, b: rgb.b })
            } else {
              throw new Error(`第${i + 1}行无效的16进制颜色值：${hexValue}`)
            }
          } else {
            throw new Error(`第${i + 1}行格式错误：${line}，应为：颜色名称,#RRGGBB`)
          }
        } else if (parts.length === 4) {
          // 格式：颜色名称,R,G,B
          const [name, rStr, gStr, bStr] = parts

          if (!name) {
            throw new Error(`第${i + 1}行颜色名称不能为空`)
          }

          const r = parseInt(rStr)
          const g = parseInt(gStr)
          const b = parseInt(bStr)

          if (isNaN(r) || isNaN(g) || isNaN(b)) {
            throw new Error(`第${i + 1}行RGB值必须是数字：${line}`)
          }

          if (r < 0 || r > 255 || g < 0 || g > 255 || b < 0 || b > 255) {
            throw new Error(`第${i + 1}行RGB值超出有效范围(0-255)：${line}`)
          }

          colorData.push({ name, r, g, b })
        } else {
          throw new Error(`第${i + 1}行格式错误：${line}，支持格式：1) #RRGGBB 2) 颜色名称,#RRGGBB 3) 颜色名称,R,G,B`)
        }
      }
    } else {
      // 格式：用逗号分隔的16进制颜色值列表
      const hexValues = inputText.split(',').map(part => part.trim()).filter(part => part)

      if (hexValues.length === 0) {
        throw new Error('没有找到有效的颜色数据')
      }

      console.log('检测到纯16进制格式，解析值：', hexValues)

      for (let i = 0; i < hexValues.length; i++) {
        const hexValue = hexValues[i]
        console.log(`处理第${i + 1}个颜色值：`, hexValue)

        if (hexValue.startsWith('#')) {
          const rgb = hexToRgb(hexValue)
          console.log(`16进制值 ${hexValue} 转换为RGB：`, rgb)

          if (rgb) {
            colorData.push({
              name: `颜色${i + 1}`,
              r: rgb.r,
              g: rgb.g,
              b: rgb.b
            })
          } else {
            throw new Error(`第${i + 1}个颜色无效的16进制值：${hexValue}`)
          }
        } else {
          throw new Error(`第${i + 1}个颜色格式错误：${hexValue}，应为：#RRGGBB`)
        }
      }
    }

    if (colorData.length === 0) {
      throw new Error('没有找到有效的颜色数据')
    }

    // 清空现有颜色并导入新颜色
    colorStore.clearCustomColors()

    for (const color of colorData) {
      colorStore.addCustomColor({
        r: color.r,
        g: color.g,
        b: color.b,
        hex: rgbToHex(color.r, color.g, color.b),
        name: color.name
      })
    }

    // 显示成功消息
    batchImportResult.value = {
      type: 'success',
      message: `成功批量导入 ${colorData.length} 个颜色`
    }

    // 清空批量导入输入框
    batchImportString.value = ''

    // 清空其他导入结果
    importResult.value = null
    exportedString.value = ''

  } catch (error) {
    console.error('批量导入颜色失败:', error)
    batchImportResult.value = {
      type: 'error',
      message: `批量导入失败：${error instanceof Error ? error.message : '未知错误'}`
    }
  }
}

// 复制到剪贴板
async function copyToClipboard() {
  try {
    await navigator.clipboard.writeText(exportedString.value)
    // 可以添加一个临时的成功提示
    const originalText = importResult.value?.message
    importResult.value = {
      type: 'success',
      message: '已复制到剪贴板！'
    }

    // 3秒后恢复原来的消息
    setTimeout(() => {
      if (importResult.value?.message === '已复制到剪贴板！') {
        importResult.value = originalText ? { type: 'success', message: originalText } : null
      }
    }, 3000)

  } catch (error) {
    console.error('复制失败:', error)
    importResult.value = {
      type: 'error',
      message: '复制失败，请手动复制'
    }
  }
}

