<template>
  <div class="usage-guide">
    <h3>{{ $t('usage.title') }}</h3>
    <ol class="steps">
      <li>{{ $t('usage.steps.1') }}</li>
      <li>{{ $t('usage.steps.2') }}</li>
      <li>{{ $t('usage.steps.3') }}</li>
    </ol>

    <div class="params">
      <h4>{{ $t('usage.params.title') }}</h4>
      <ul>
        <li>
          <strong>{{ $t('usage.params.artStyle') }}</strong>
        </li>
        <li>
          <strong>{{ $t('usage.params.dmc') }}</strong>
        </li>
        <li>
          <strong>{{ $t('usage.params.merge') }}</strong>
        </li>
        <li>
          <strong>{{ $t('usage.params.custom') }}</strong>
        </li>
      </ul>
    </div>

    <div class="downloads" v-if="hasAny">
      <div class="block" v-if="imageItems.length">
        <h4>{{ $t('usage.downloads.images') }}</h4>
        <div class="file-list">
          <div class="file" v-for="item in imageItems" :key="item.name">
            <img :src="item.url" :alt="item.name" />
            <div class="meta">
              <span class="name">{{ item.name }}</span>
              <a :href="item.url" :download="item.name" class="btn-link">{{ $t('usage.downloads.downloadImage') }}</a>
            </div>
          </div>
        </div>
      </div>

      <div class="block" v-if="excelItems.length">
        <h4>{{ $t('usage.downloads.excel') }}</h4>
        <ul class="excel-list">
          <li v-for="item in excelItems" :key="item.name">
            <span class="name">{{ item.name }}</span>
            <a :href="item.url" :download="item.name" class="btn-link">{{ $t('usage.downloads.downloadExcel') }}</a>
          </li>
        </ul>
      </div>
    </div>

    <p v-else class="empty-tip">{{ $t('usage.empty') }}</p>
  </div>
</template>

<script setup lang="ts">
import { computed } from 'vue'

// 通过 Vite 的 import.meta.glob 收集示例资源
// 使用 as: 'url' 强制按静态资源 URL 处理，避免被当作 JS 解析
const imageModules = import.meta.glob('../assets/effect/*.{png,jpg,jpeg,gif,webp,bmp,svg}', { eager: true, as: 'url' }) as Record<string, string>
const excelModules = import.meta.glob('../assets/effect/*.{xls,xlsx,csv}', { eager: true, as: 'url' }) as Record<string, string>

type Item = { name: string; url: string }

function toItems(mods: Record<string, string>): Item[] {
  return Object.entries(mods).map(([path, url]) => {
    const name = path.split('/').pop() || path
    return { name, url } as Item
  })
}

const imageItems = toItems(imageModules)
const excelItems = toItems(excelModules)
const hasAny = computed(() => imageItems.length > 0 || excelItems.length > 0)
</script>

